                     (strncmp(g_brk_ser_var, "_brkser", 7) == 0 || light);
      const char *sfx = brk_goto ? g_brk_ser_var + (light ? 6 : 7) : NULL;   /* wrapper temp id */
      emit_indent(b, indent);
