      if (brk_goto && light) buf_printf(b, "_brkv%s = ", sfx);
      else if (brk_goto) buf_printf(b, "sp_brk_val[_brkslot%s - 1] = ", sfx);
      else buf_printf(b, "sp_brk_throw(%s, ", g_brk_ser_var);
